(() => {
 'use strict';
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],T=window.Tom;
 const page=document.body.dataset.page||'home';
 function section(id,eyebrow,title,subtitle){const s=document.createElement('section');s.id=id;s.className='premium-section';s.innerHTML=`<div class="section-heading reveal"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div><p>${subtitle}</p></div>`;return s;}
 function swap(el){el.classList.remove('content-swap');void el.offsetWidth;el.classList.add('content-swap')}
 if(page==='home'){
   const ribbon=document.createElement('div');ribbon.className='journey-ribbon';ribbon.innerHTML='<span>THE FIELD JOURNAL / ALWAYS IN PROGRESS</span><span data-world-count>0 / 3 WORLDS EXPLORED</span><button>OPEN YOUR DISCOVERIES ↗</button>';$('.ticker').after(ribbon);$('button',ribbon).onclick=()=>T.open($('#discoveries'));
   const now=section('now','04 / NOTES FROM THE WORKBENCH','Curiosity doesn’t<br><span class="muted">really clock out.</span>','A few threads I keep coming back to.<br>Studio notes, not a live activity feed.');
   now.innerHTML+='<div class="now-grid reveal" id="now-grid"></div><div class="journal-controls"><button class="text-button" id="edit-now">TRY A LOCAL JOURNAL DRAFT ↗</button><span class="local-label" id="now-label">These notes reflect my interests and projects.</span></div>';
   $('.closing').before(now);
   const defaults={building:'Tools that connect back to real interests: Explore NY, GalleryX, and this little corner of the internet.',learning:'Computer science at SUNY Poly, and the things a project teaches you that a tutorial never quite covers.',outside:'Wildlife photography, time on the water, and finding the next excuse to get into the Adirondacks.'};
   const saved=T.store.read('tom-now-local-v3',null);let notes=saved&&typeof saved==='object'?{...defaults,...saved}:{...defaults};
   function nowRender(){const out=$('#now-grid');out.replaceChildren();[['building','BUILDING','One more idea.'],['learning','LEARNING','Figuring it out.'],['outside','OUTSIDE','The scenic route.']].forEach(([key,label,title])=>{const a=document.createElement('article');a.className='now-card';const l=document.createElement('span');l.className='eyebrow';l.textContent=label;const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=String(notes[key]).slice(0,600);a.append(l,h,p);out.append(a)});$('#now-label').textContent=JSON.stringify(notes)===JSON.stringify(defaults)?'These notes reflect my interests and projects.':'Showing your local draft. It does not change the published portfolio.';}
   const journal=T.modal('local-journal','Notes in progress.','<p class="dialog-intro">Try writing a new studio update. This draft is visible only in this browser—not published and not an admin editor.</p><form class="journal-form" id="journal-form">'+['building','learning','outside'].map(k=>`<label>${k.toUpperCase()}<textarea name="${k}" maxlength="600" required></textarea></label>`).join('')+'<button class="outline-button" type="submit">Save draft on this device</button><button class="text-button" id="journal-reset" type="button">Restore original notes</button></form>');
   $('#edit-now').onclick=()=>{for(const k in defaults)$(`[name="${k}"]`,journal).value=notes[k];T.open(journal)};$('#journal-form').onsubmit=e=>{e.preventDefault();notes=Object.fromEntries(new FormData(e.target));T.store.write('tom-now-local-v3',notes);nowRender();journal.close();T.notify('Local draft saved. Published content is unchanged.')};$('#journal-reset').onclick=()=>{notes={...defaults};T.store.write('tom-now-local-v3',notes);nowRender();journal.close()};nowRender();
   const connect=document.createElement('section');connect.className='connection-section';connect.id='connections';connect.innerHTML='<div class="connection-inner"><span class="eyebrow">05 / THE THREAD THROUGH EVERYTHING</span><h2>It was never<br>just <span class="text-accent">one thing.</span></h2><div class="connection-layout"><div class="connection-steps">'+['Go outside','Notice a moment','Make something','Find a problem','Build an idea','Go again'].map((t,i)=>`<button data-connection="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${t}</button>`).join('')+'</div><article class="connection-story" id="connection-story" aria-live="polite"></article></div><p class="finale-note" id="finale-note">Follow all three worlds to find the common thread.</p></div>';
   $('.closing').before(connect);
   const connections=[['01','A reason to head out.','A lake, a trail, a small camp. Getting outside gives me something real to pay attention to.'],['02','A frame worth keeping.','The camera changes the way I look. A bird, a reflection, a line in the landscape—something I might otherwise walk past.'],['03','The edit becomes the story.','Photos and footage turn into an image, a sequence, or a little piece of a trip worth sharing.'],['04','“There has to be a better way.”','Too many photos to sort. Too many places to remember. A workflow that could be a little easier.'],['05','The problem becomes a project.','GalleryX and Explore NY come from the same place: taking something I care about and trying to build a useful tool around it.'],['06','Another reason to explore.','The next project sends me back outside. Code, cameras, and curiosity keep feeding into each other.']];let active=-1;
   function connection(i){if(active===i)return;active=i;const [n,title,text]=connections[i];$('#connection-story').innerHTML=`<span class="connection-number">${n}</span><h3>${title}</h3><p>${text}</p>`;$$('[data-connection]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.connection)===i);b.setAttribute('aria-pressed',String(Number(b.dataset.connection)===i))});swap($('#connection-story'))}
   $$('[data-connection]').forEach(b=>b.onclick=()=>connection(Number(b.dataset.connection)));let scrollScheduled=false;addEventListener('scroll',()=>{if(scrollScheduled||innerWidth<750||!T.motion())return;scrollScheduled=true;requestAnimationFrame(()=>{const r=connect.getBoundingClientRect();if(r.top<innerHeight*.35&&r.bottom>innerHeight*.4){const progress=Math.max(0,Math.min(1,(innerHeight*.35-r.top)/(r.height-innerHeight*.5)));connection(Math.min(5,Math.floor(progress*6)))}scrollScheduled=false})},{passive:true});connection(0);T.renderDiscoveries();
 }
 if(page.includes('code')){
   const timeline=section('project-stories','04 / THE THINKING BEHIND THE BUILD','Ideas have<br><span class="muted">a backstory.</span>','The origin, approach, and next questions.<br>Project notes—not invented launch dates.');
   const data={
    explore:{name:'Explore NY',status:'In development',origin:'A place to bring outdoor locations, maps, trips, and personal progress together.',approach:'Next.js for the interface, MapLibre for the map, and Supabase for structured data. The planned data model includes places, visits, field reports, trips, and collections.',challenge:'Keeping place information useful and trustworthy while making the map feel simple to explore.',state:'A development project centered on New York outdoor discovery, with interest in official campsite and lean-to data.',next:'Refine place detail, collection, and trip flows; keep source information clear.'},
    gallery:{name:'GalleryX',status:'Project concept & development',origin:'A growing media collection, external drives, and a desire for an easier way to find the good stuff.',approach:'A Mac and Windows desktop gallery organized around scanning media, reviewing exports, identifying duplicates, and browsing video.',challenge:'Organizing a large collection without losing track of where the files actually live.',state:'The workflow and feature direction are defined. This portfolio does not provide a released app download.',next:'Make discovery, duplicate review, and exports feel like one coherent workflow.'},
    focused:{name:'Focused on Tom',status:'You’re exploring it',origin:'A portfolio that feels like exploring the person behind the work.',approach:'Three connected worlds, a shared visual language, and small tools that make each interest tangible.',challenge:'Balancing expressive motion with readable content, responsive layouts, and accessible controls.',state:'A live, evolving portfolio with a local darkroom, interactive labs, and customizable appearance.',next:'Add original photographs and keep improving the stories as the real projects evolve.'},
    trips:{name:'Trip planner',status:'App concept',origin:'Making it easier for a small friend group to keep a trip organized.',approach:'An offline-capable web interface for plans, shared trip information, and the practical details of getting out the door.',challenge:'Making the plan useful when connectivity is limited and different people need different details.',state:'A direction for a small-group planning tool, not a released service linked here.',next:'Focus on the essentials: the plan, the packing, and the information worth keeping offline.'},
    multiview:{name:'Multi-video viewer',status:'Web project idea',origin:'Watch several videos or streams in one clean local workspace.',approach:'Paste links on separate lines, arrange multiple players, and keep individual controls accessible.',challenge:'Different sites handle embedding differently; not every video source permits an embedded player.',state:'A local web-tool idea focused on practical viewing and understandable fallbacks.',next:'Make supported sources clear and handle blocked embeds honestly.'},
    islands:{name:'Six islands',status:'Minecraft concept',origin:'A progression world where players need to trade and help each other without sharing one global quest log.',approach:'Divide six islands among one to six players, control access, and distribute resources unevenly.',challenge:'Encouraging cooperation while keeping each player’s progression meaningful.',state:'A game-system concept. The island lab above is an illustrative model, not a released mod.',next:'Develop individual quest paths, resource balance, and clear permission rules.'}
   };
   timeline.innerHTML+='<div class="story-selector">'+Object.entries(data).map(([k,v],i)=>`<button class="pill-button ${i===0?'active':''}" data-story="${k}" aria-pressed="${i===0}">${v.name}</button>`).join('')+'</div><div class="story-layout" id="story-layout" aria-live="polite"></div>';
   $('.code-story').before(timeline);
   function story(key){const d=data[key];$('#story-layout').innerHTML=`<aside class="story-overview"><span class="eyebrow">PROJECT FIELD NOTES</span><h3>${d.name}</h3><span class="story-status">${d.status}</span><p>${d.origin}</p><span class="fine-print">The stages below describe the thinking, not a dated delivery history.</span></aside><div class="story-timeline">${[['THE SPARK','origin'],['THE APPROACH','approach'],['THE HARD PART','challenge'],['WHERE IT STANDS','state'],['THE NEXT QUESTION','next']].map(([label,k],i)=>`<article class="story-step"><span>0${i+1} / ${label}</span><h4>${['Why it exists','How I’d approach it','What needs solving','An honest snapshot','What comes next'][i]}</h4><p>${d[k]}</p></article>`).join('')}</div>`;$$('[data-story]').forEach(b=>{b.classList.toggle('active',b.dataset.story===key);b.setAttribute('aria-pressed',String(b.dataset.story===key))});swap($('#story-layout'))}
   $$('[data-story]').forEach(b=>b.onclick=()=>story(b.dataset.story));story('explore');
   const quick=$('.terminal-quick');['theme blue','theme random','open boat','timeline','surprise','lightsout'].forEach(c=>{const b=document.createElement('button');b.textContent=c;b.onclick=()=>{const output=$('#terminal-output');const q=document.createElement('p');q.className='terminal-command';q.textContent='tom ~ $ '+c;const a=document.createElement('p');a.textContent=T.command(c);output.append(q,a);output.scrollTop=output.scrollHeight};quick.append(b)});
 }
 if(page.includes('grid')){
   const map=section('explore-map','THE EXPLORER’S INDEX','A few places.<br><span class="muted">A lot of possibility.</span>','An illustrated regional index of my outdoor interests.<br>Select a place to open its field note.');
   const locations={cranberry:{name:'Cranberry Lake',x:28,y:23,kicker:'BOAT-CAMPING IDEAS',text:'A setting I’ve been thinking about for a boat-camping trip: time on the water, a camp setup, fishing, and filming the experience.',activity:'Boat camping / fishing / filming',gear:'Boat kit, camp setup, camera and audio gear',connection:'Trip-planning ideas and outdoor storytelling'},adk:{name:'Adirondacks',x:68,y:30,kicker:'TRAILS & SMALL CAMPS',text:'The larger backdrop to a lot of my outdoor interests. Hiking, backpacking, wildlife, and landscapes all meet here.',activity:'Hiking / backpacking / photography',gear:'REI Flash 55, NEMO Hornet, camera',connection:'Explore NY and places worth remembering'},inlet:{name:'Inlet',x:53,y:48,kicker:'TIME AWAY',text:'Part of my Adirondack orbit: lakes, trails, and time outside with a camera along for the trip.',activity:'Lake days / short hikes / film',gear:'Everyday camera setup and day gear',connection:'Turning a trip into a visual story'},hinckley:{name:'Hinckley Reservoir',x:70,y:69,kicker:'ANOTHER STRETCH OF WATER',text:'One of the waters in my fishing interests beyond Delta. A different setting for the same curiosity about boating and fishing.',activity:'Fishing / boating',gear:'Fishing setup and boat essentials',connection:'The water side of my outdoor world'},delta:{name:'Delta Lake',x:31,y:80,kicker:'FAMILIAR WATER',text:'The lake that shows up most often in my fishing and boating life. Bass, pickerel, time in the MirroCraft, and a camera when the moment is there.',activity:'Bass & pickerel / boating / wildlife',gear:'MirroCraft, fishing rods, Garmin Striker',connection:'Delta wildlife and outdoor field notes'}};
   map.innerHTML+='<div class="field-map-layout reveal"><div class="field-map"><span class="map-axis north">N / REGIONAL INDEX</span><span class="map-regions">UPSTATE NEW YORK</span>'+Object.entries(locations).map(([k,p])=>`<button class="map-pin" data-map="${k}" style="left:${p.x}%;top:${p.y}%" aria-pressed="false"><span></span>${p.name}</button>`).join('')+'<span class="map-axis south">SCHEMATIC · NOT FOR NAVIGATION</span></div><aside class="map-inspector" id="map-inspector" aria-live="polite"></aside></div><p class="fine-print">Locations are arranged schematically, not plotted to geographic scale. This is a portfolio field index—not directions, launch conditions, access guidance, or a live map.</p>';
   $('#field-guide').after(map);
   function location(key){const p=locations[key];$('#map-inspector').innerHTML=`<span class="eyebrow">${p.kicker}</span><h3>${p.name}</h3><p>${p.text}</p><div class="map-fact"><b>THE ACTIVITY</b>${p.activity}</div><div class="map-fact"><b>THE KIT</b>${p.gear}</div><div class="map-fact"><b>THE CONNECTION</b>${p.connection}</div>`;$$('[data-map]').forEach(b=>{b.classList.toggle('active',b.dataset.map===key);b.setAttribute('aria-pressed',String(b.dataset.map===key))});swap($('#map-inspector'))}
   $$('[data-map]').forEach(b=>b.onclick=()=>{location(b.dataset.map);T.unlock('map')});location('delta');
   const boat=section('boat-lab','THE MIRROCRAFT / AN ONGOING PROJECT','Built for the water.<br><span class="muted">Always being figured out.</span>','Inspect the current setup.<br>Switch on the proposed upgrades.');
   const parts={motor:['Yamaha 30 hp','1988 Yamaha 30 hp two-stroke tiller outboard, with electric start and manual tilt. A big part of learning this boat has been understanding the motor.','CURRENT'],sonar:['Garmin Striker Vivid 5cv','The current fish finder. It’s part of the setup for understanding the water beneath the boat.','CURRENT'],rods:['Fishing setup','A medium spinning combo and a medium-heavy baitcaster are part of the mix, with bass and pickerel as regular targets.','CURRENT'],deck:['Deck & drainage','An idea for improving the deck, cleaning up the hull, and thinking through how water drains. The graphic is conceptual—not a structural or construction plan.','PROPOSED'],bow:['Bow electronics','An additional bow unit and a possible future LiveScope path have been part of the planning. Not shown as installed.','PROPOSED'],trolling:['Bow trolling motor','A bow-mounted trolling motor with position-holding capability is on the wish list. This diagram is a layout idea, not a compatibility assessment.','PROPOSED']};
   const spots=[['motor',270,480,'01'],['sonar',340,345,'02'],['rods',185,285,'03'],['deck',270,235,'04'],['bow',285,115,'05'],['trolling',245,68,'06']];
   boat.innerHTML=`<div class="boat-layout reveal"><div class="boat-drawing"><span class="eyebrow">16 FT / ALUMINUM DEEP-V</span><svg viewBox="0 0 540 540" role="img" aria-labelledby="boat-diagram-title"><title id="boat-diagram-title">Conceptual top-down layout of Tom’s MirroCraft. Numbered points match the inspection controls.</title><g fill="none" stroke="currentColor" stroke-width="1.4"><path d="M270 45 Q162 115 150 220 L150 455 Q270 482 390 455 L390 220 Q378 115 270 45Z"/><path d="M270 62 Q176 125 167 225 L167 438 Q270 461 373 438 L373 225 Q364 125 270 62Z" opacity=".4"/><path d="M167 345H373M167 370H373M167 265H373M167 284H373"/><rect x="250" y="461" width="40" height="43"/><path d="M112 48V455M107 48H117M107 455H117" opacity=".5"/><g class="planned" data-plan="deck"><path d="M170 225H370L348 160H192Z"/><path d="M270 230V422"/></g><g class="planned" data-plan="bow"><rect x="295" y="110" width="42" height="26"/><path d="M316 137V150"/></g><g class="planned" data-plan="trolling"><path d="M236 70L222 40L242 28M219 26L252 31"/></g></g><text x="94" y="260" transform="rotate(-90 94 260)">16 FT HULL · CONCEPT VIEW</text><text x="403" y="461">STERN</text><text x="293" y="44">BOW</text>${spots.map(([key,x,y,num])=>`<g class="boat-diagram-point" data-part-svg="${key}" role="button" tabindex="0" aria-label="Inspect ${parts[key][0]}"><circle cx="${x}" cy="${y}" r="15"/><text x="${x}" y="${y}">${num}</text></g>`).join('')}</svg><p class="boat-caption">SOLID / CURRENT LAYOUT &nbsp; DASHED / IDEAS<br>Conceptual arrangement—not to scale and not an engineering drawing.</p></div><div class="boat-controls"><span class="eyebrow">1980 MIRROCRAFT FISHERMAN</span><h3>A boat with<br>a few stories.</h3><label class="toggle-row">Show planned upgrades<input type="checkbox" id="boat-build"></label><div class="boat-hotspots">${Object.entries(parts).map(([k,v],i)=>`<button data-part="${k}" aria-pressed="false">0${i+1} / ${v[0]}</button>`).join('')}</div><div class="boat-detail" id="boat-detail" aria-live="polite"></div></div></div>`;
   map.after(boat);function part(key){const [name,text,status]=parts[key];$('#boat-detail').innerHTML=`<span class="eyebrow">${status}</span><h4>${name}</h4><p>${text}</p>`;$$('[data-part]').forEach(b=>{b.classList.toggle('active',b.dataset.part===key);b.setAttribute('aria-pressed',String(b.dataset.part===key))});$$('[data-part-svg]').forEach(b=>b.classList.toggle('active',b.dataset.partSvg===key));}
   $$('[data-part]').forEach(b=>b.onclick=()=>{part(b.dataset.part);T.unlock('boat')});$$('[data-part-svg]').forEach(b=>{b.onclick=()=>{part(b.dataset.partSvg);T.unlock('boat')};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.dispatchEvent(new MouseEvent('click',{bubbles:true}))}}});$('#boat-build').onchange=e=>{$('.boat-drawing').classList.toggle('build-mode',e.target.checked);T.unlock('boat')};part('motor');
   // Replace the three basic checklists with six activity-specific, explained loadouts.
   const gear={water:['Water & GRAYL purifier','Water and a way to treat it are part of my outdoor kit.'],rain:['Rain jacket & rain pants','A layer for changing weather.'],aid:['First-aid kit','Part of the essentials I bring along; this list isn’t a complete safety checklist.'],light:['NU25 headlamp','Hands-free light around camp or when a day runs late.'],power:['Anker 20,000 mAh power bank','Portable power for small electronics and camera-related gear.'],camera:['Sony A6700','For the moments worth keeping.'],pack:['REI Flash 55','The backpack in my overnight setup.'],tent:['NEMO Hornet OSMO + footprint','My lightweight shelter and footprint.'],sleep:['Sleep setup & pillow','The pad, sleep system, and a little comfort for a night outside.'],cook:['Jetboil Flash','A compact cooking setup from my camping kit.'],food:['Food & bear canister','Food and storage appropriate to the trip. Local requirements still need to be checked separately.'],wide:['Sigma 10–18mm / Tamron 17–70mm','Choose a wide environmental view or the flexible everyday zoom.'],gm:['Sony 70–200mm f/2.8 GM','A telephoto perspective without going all the way to the super-telephoto.'],tele:['Sony 200–600mm','For wildlife and distant details.'],tripod:['Tripod','Support for a steady frame when the situation allows it.'],boat:['MirroCraft & boating essentials','The boat setup, personal flotation, and trip-specific safety equipment. This is only a portfolio gear overview.'],rods:['Fishing rods & tackle','A spinning or baitcasting setup and tackle for the day.'],sonar:['Garmin Striker Vivid 5cv','The fish finder in the current boat setup.'],audio:['DJI Mic 2','Capturing clearer dialogue and close-up sounds for a video.'],drone:['DJI Mini 4 Pro','An aerial perspective where flying is allowed.'],pocket:['Osmo Pocket 3','A compact option for motion and a different viewpoint.'],shotlist:['Shot list','A plan for the sequence: wide shot, detail, action, sound, and the final edit.']};
   const packs={day:{name:'Day hike',ids:['water','rain','aid','light','power','camera']},night:{name:'Overnight',ids:['pack','tent','sleep','cook','food','water','rain','aid','light','power']},boat:{name:'Boat camping',ids:['boat','tent','sleep','cook','food','water','aid','light','rods','camera']},photo:{name:'Photo trip',ids:['camera','wide','gm','tele','tripod','power','water','rain']},fishing:{name:'Fishing day',ids:['boat','rods','sonar','water','rain','aid','light']},film:{name:'Car shoot',ids:['camera','wide','gm','tripod','audio','pocket','shotlist','power']}};
   const layout=$('#pack .pack-layout');layout.innerHTML='<div><div class="loadout-tabs">'+Object.entries(packs).map(([k,v],i)=>`<button class="pill-button ${i===0?'active':''}" data-loadout="${k}" aria-pressed="${i===0}">${v.name}</button>`).join('')+'</div><div id="loadout-list"></div><div class="loadout-detail" id="loadout-detail" aria-live="polite">Tap an item’s information button to see why it comes along.</div><div class="loadout-actions"><button class="outline-button" id="loadout-download">Download this checklist ↗</button></div></div><aside class="pack-summary"><span class="eyebrow">READY WHEN YOU ARE</span><div class="pack-number"><span id="loadout-count">0</span><span id="loadout-total"></span></div><div class="pack-meter"><div id="loadout-bar"></div></div><p id="loadout-message" aria-live="polite"></p><button class="outline-button" id="loadout-reset">Reset this kit ↺</button><p class="fine-print">A personal gear overview, not a complete safety checklist. Checks are saved on this device. Equipment needs depend on the trip and conditions.</p></aside>';
   let selected='day';const savedChecks=T.store.read('tom-loadouts-v3',[]);const checked=new Set(Array.isArray(savedChecks)?savedChecks:[]);
   function count(){const ids=packs[selected].ids,n=ids.filter(x=>checked.has(x)).length;$('#loadout-count').textContent=n;$('#loadout-total').textContent='/ '+ids.length;$('#loadout-bar').style.width=n/ids.length*100+'%';$('#loadout-message').textContent=n===ids.length?'This kit is checked. The horizon is calling.':`${ids.length-n} more item${ids.length-n===1?'':'s'} in this kit.`;if(n===ids.length)T.unlock('packed');T.store.write('tom-loadouts-v3',[...checked])}
   function loadout(){const list=$('#loadout-list');list.replaceChildren();packs[selected].ids.forEach(id=>{const row=document.createElement('div');row.className='loadout-row';const label=document.createElement('label'),check=document.createElement('input'),name=document.createElement('span'),info=document.createElement('button');check.type='checkbox';check.checked=checked.has(id);name.textContent=gear[id][0];check.onchange=()=>{check.checked?checked.add(id):checked.delete(id);count()};info.textContent='i';info.setAttribute('aria-label','Why bring '+gear[id][0]);info.onclick=()=>{$('#loadout-detail').innerHTML=`<strong>${gear[id][0]}</strong>${gear[id][1]}`};label.append(check,name);row.append(label,info);list.append(row)});count();$$('[data-loadout]').forEach(b=>{b.classList.toggle('active',b.dataset.loadout===selected);b.setAttribute('aria-pressed',String(b.dataset.loadout===selected))})}
   $$('[data-loadout]').forEach(b=>b.onclick=()=>{selected=b.dataset.loadout;loadout()});$('#loadout-reset').onclick=()=>{packs[selected].ids.forEach(id=>checked.delete(id));loadout()};$('#loadout-download').onclick=()=>{const text='FOCUSED ON TOM / '+packs[selected].name.toUpperCase()+'\n\n'+packs[selected].ids.map(id=>`[${checked.has(id)?'x':' '}] ${gear[id][0]}`).join('\n')+'\n\nPersonal gear overview only—not a complete safety checklist.';const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='focused-on-tom-'+selected+'-checklist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};loadout();
   const light=document.createElement('button');light.className='outline-button';light.style.marginTop='25px';light.textContent='TRY FLASHLIGHT MODE ↗';light.onclick=()=>T.command('lightsout');$('#overlap').append(light);
 }
 T.reveal();
})();
